create or replace function phase10k3_test.assert(input_condition boolean,input_label text)
returns void language plpgsql as $$ begin if not coalesce(input_condition,false) then raise exception 'FAIL %',input_label; end if; raise notice 'PASS %',input_label; end $$;

select phase10k3_test.assert((select ui_release_stage='staff_preview' from public.routine_organization_settings where organization_id='a1000000-0000-4000-8000-000000000001'),'001 release stage advances to staff_preview');
select phase10k3_test.assert((select ui_contract_version='phase10k3-v1' from public.routine_organization_settings where organization_id='a1000000-0000-4000-8000-000000000001'),'002 contract is phase10k3-v1');
select phase10k3_test.assert((select mode='shadow' from public.routine_organization_settings where organization_id='a1000000-0000-4000-8000-000000000001'),'003 mode remains shadow');
select phase10k3_test.assert(not exists(select 1 from public.routine_organization_settings where mode in('pilot','active')),'004 no pilot or active mode');
select phase10k3_test.assert(not exists(select 1 from public.routine_organization_settings where ui_release_stage in('pilot_ready','production_ready')),'005 no later release stage activated');
select phase10k3_test.assert((select value::text~*'pilot' from phase10k3_test.state where key='pilot_rejected'),'006 pilot gate rejects staff_preview');
select phase10k3_test.assert((select value::text~*'active|production' from phase10k3_test.state where key='active_rejected'),'007 active gate rejects staff_preview');
select phase10k3_test.assert((select value='true'::jsonb from phase10k3_test.state where key='shadow_mutation_rejected'),'008 shadow rejects lifecycle mutation');
select phase10k3_test.assert((select count(*)=6 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('get_routine_employee_home','get_routine_run_action_context','get_routine_task_action_context','get_routine_handover_action_context','get_routine_transfer_action_context','get_double_shift_action_context')),'009 six employee read RPCs installed');
select phase10k3_test.assert((select count(*)=6 from information_schema.role_routine_grants where specific_schema='public' and routine_name in('get_routine_employee_home','get_routine_run_action_context','get_routine_task_action_context','get_routine_handover_action_context','get_routine_transfer_action_context','get_double_shift_action_context') and grantee='authenticated' and privilege_type='EXECUTE'),'010 exact authenticated grants');
select phase10k3_test.assert(not exists(select 1 from information_schema.role_routine_grants where specific_schema='public' and routine_name in('get_routine_employee_home','get_routine_run_action_context','get_routine_task_action_context','get_routine_handover_action_context','get_routine_transfer_action_context','get_double_shift_action_context') and grantee in('PUBLIC','anon')),'011 no public or anon grants');
select phase10k3_test.assert(not exists(select 1 from information_schema.role_routine_grants where specific_schema='public' and routine_name in('routine_phase10k3_employee_context','routine_phase10k3_action','routine_phase10k3_sanitize_row') and grantee in('PUBLIC','anon','authenticated')),'012 private helpers remain private');
select phase10k3_test.assert((select count(*)=6 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('get_routine_employee_home','get_routine_run_action_context','get_routine_task_action_context','get_routine_handover_action_context','get_routine_transfer_action_context','get_double_shift_action_context') and p.proconfig@>array['search_path=pg_catalog']),'013 every read RPC fixes search_path');
select phase10k3_test.assert(not exists(select 1 from information_schema.role_table_grants where table_schema='public' and table_name like 'routine_%' and grantee='authenticated' and privilege_type in('INSERT','UPDATE','DELETE')),'014 no direct table DML grants');
select phase10k3_test.assert((select value='true'::jsonb from phase10k3_test.state where key='nonmember_rejected'),'015 staff without membership rejected');
select phase10k3_test.assert((select value='true'::jsonb from phase10k3_test.state where key='device_rejected'),'016 shared device without session rejected');
select phase10k3_test.assert((select value='true'::jsonb from phase10k3_test.state where key='cross_org_rejected'),'017 cross organization rejected');
select phase10k3_test.assert((select value->>'contractVersion'='phase10k3-v1' from phase10k3_test.state where key='manager_home'),'018 manager employee contract returned');
select phase10k3_test.assert((select value->>'mode'='shadow' from phase10k3_test.state where key='manager_home'),'019 manager home reports shadow');
select phase10k3_test.assert((select (value->>'readOnlyPreview')::boolean from phase10k3_test.state where key='manager_home'),'020 manager home is read-only preview');
select phase10k3_test.assert((select not (value->>'operationalAllowed')::boolean from phase10k3_test.state where key='manager_home'),'021 operational access false');
select phase10k3_test.assert((select value->>'readOnlyMessage'='Read-only preview — operational actions are not enabled' from phase10k3_test.state where key='manager_home'),'022 exact read-only message');
select phase10k3_test.assert((select value->'operationalClock' ?& array['serverNow','operationalDate','timezone'] from phase10k3_test.state where key='manager_home'),'023 server clock and date returned');
select phase10k3_test.assert((select value->'identity'->>'actorSource'='personal_auth' from phase10k3_test.state where key='manager_home'),'024 manager identity is personal');
select phase10k3_test.assert((select value->'identity'->>'role'='manager' from phase10k3_test.state where key='manager_home'),'025 manager role from server');
select phase10k3_test.assert((select jsonb_typeof(value->'currentRuns')='array' from phase10k3_test.state where key='manager_home'),'026 current runs structured');
select phase10k3_test.assert((select value->'joinableRuns'='[]'::jsonb from phase10k3_test.state where key='manager_home'),'027 joinable runs disabled in shadow');
select phase10k3_test.assert((select jsonb_typeof(value->'startableTemplates')='array' from phase10k3_test.state where key='manager_home'),'028 published templates structured');
select phase10k3_test.assert((select not exists(select 1 from jsonb_array_elements(value->'startableTemplates') entry where (entry->'action'->>'allowed')::boolean) from phase10k3_test.state where key='manager_home'),'029 template start actions false in shadow');
select phase10k3_test.assert((select jsonb_typeof(value->'doubleShiftBundles')='array' from phase10k3_test.state where key='manager_home'),'030 bundles structured');
select phase10k3_test.assert((select jsonb_typeof(value->'assignedTasks')='array' from phase10k3_test.state where key='manager_home'),'031 assigned tasks structured');
select phase10k3_test.assert((select jsonb_typeof(value->'openDeviations')='array' from phase10k3_test.state where key='manager_home'),'032 deviations structured');
select phase10k3_test.assert((select jsonb_typeof(value->'pendingHandovers')='array' from phase10k3_test.state where key='manager_home'),'033 handovers structured');
select phase10k3_test.assert((select jsonb_typeof(value->'pendingTransfers')='array' from phase10k3_test.state where key='manager_home'),'034 transfers structured');
select phase10k3_test.assert((select jsonb_typeof(value->'eventTransferRequests')='array' from phase10k3_test.state where key='manager_home'),'035 event transfer requests structured');
select phase10k3_test.assert((select value->'sync'->>'serverConfirmed'='true' from phase10k3_test.state where key='manager_home'),'036 server cache marked confirmed');
select phase10k3_test.assert((select value->'offline'->>'criticalActionsOnlineOnly'='true' from phase10k3_test.state where key='manager_home'),'037 critical actions online only');
select phase10k3_test.assert((select (value->>'readOnlyPreview')::boolean and value->'identity'->>'role'='staff' from phase10k3_test.state where key='staff_home'),'038 preview member staff read-only');
select phase10k3_test.assert((select value->'identity'->>'actorSource'='shared_device_operator' from phase10k3_test.state where key='shared_home'),'039 shared effective identity returned');
select phase10k3_test.assert((select (value->>'readOnlyPreview')::boolean from phase10k3_test.state where key='shared_home'),'040 shared operator read-only');
select phase10k3_test.assert((select value->'sync'->>'transport'='cursor_polling' from phase10k3_test.state where key='shared_home'),'041 shared operator uses cursor polling');
select phase10k3_test.assert(not exists(select 1 from phase10k3_test.state where value::text~*'pin_hash|session_secret_hash|sessionToken|operatorSessionToken|rawOperations'),'042 no secrets or operations leak');
select phase10k3_test.assert((select value ?& array['run','participant','actorRole','actions','progress','completionValidation','offlinePolicy'] from phase10k3_test.state where key='run_context'),'043 run action context complete');
select phase10k3_test.assert((select value->'actions' ?& array['canJoin','canStartRun','canRequestFinalVerification','canVerifyRun','canFinish','canReopen','canCancel'] from phase10k3_test.state where key='run_context'),'044 seven run actions returned');
select phase10k3_test.assert((select not exists(select 1 from jsonb_each(value->'actions') action where (action.value->>'allowed')::boolean) from phase10k3_test.state where key='run_context'),'045 all run actions false in shadow');
select phase10k3_test.assert((select not exists(select 1 from jsonb_each(value->'actions') action where action.value->>'reasonCode'<>'routine_ui_operational_access_required') from phase10k3_test.state where key='run_context'),'046 run shadow reason codes authoritative');
select phase10k3_test.assert((select value->'progress' ?& array['total','handled','remaining','criticalRemaining','blocked'] from phase10k3_test.state where key='run_context'),'047 progress counts complete');
select phase10k3_test.assert((select value->'offlinePolicy'->>'serverReceiptRequired'='true' from phase10k3_test.state where key='run_context'),'048 run receipt required');
select phase10k3_test.assert((select value ?& array['task','timing','dependencyStatus','actorRelationship','initialAssessmentPolicy','items','notApplicablePolicy','criticality','verificationPolicy','activeDeviations','referenceImages','actions','offlinePolicy'] from phase10k3_test.state where key='task_context'),'049 task context complete');
select phase10k3_test.assert((select value->'actions' ?& array['canClaim','canRelease','canStart','canPause','canAssess','canUpdateItems','canComment','canBlock','canMarkNotApplicable','canComplete','canReopen','canVerify','canTransfer'] from phase10k3_test.state where key='task_context'),'050 thirteen task actions returned');
select phase10k3_test.assert((select not exists(select 1 from jsonb_each(value->'actions') action where (action.value->>'allowed')::boolean) from phase10k3_test.state where key='task_context'),'051 all task actions false in shadow');
select phase10k3_test.assert((select value->'timing' ? 'serverNow' from phase10k3_test.state where key='task_context'),'052 task timing uses server instant');
select phase10k3_test.assert((select value->'dependencyStatus' ?& array['valid','blockers','dependencies'] from phase10k3_test.state where key='task_context'),'053 dependency validation returned');
select phase10k3_test.assert((select value->'offlinePolicy' ?& array['completionQueueAllowed','timedNotApplicableOnlineOnly','sharedCriticalOnlineOnly'] from phase10k3_test.state where key='task_context'),'054 offline policy explicit');
select phase10k3_test.assert((select value->'actions' ?& array['canEdit','canRefresh','canSubmit','canAccept'] from phase10k3_test.state where key='handover_context'),'055 handover action context complete');
select phase10k3_test.assert((select value ?& array['handover','items','actorRelation'] from phase10k3_test.state where key='handover_context'),'056 handover sanitized workspace returned');
select phase10k3_test.assert((select value->'actions' ?& array['canAccept','canReject','canComplete','canCancel'] from phase10k3_test.state where key='transfer_context'),'057 transfer action context complete');
select phase10k3_test.assert((select value ?& array['transfer','sourceTask','actorRelation'] from phase10k3_test.state where key='transfer_context'),'058 limited transfer workspace returned');
select phase10k3_test.assert((select value->'actions' ?& array['canConfirmDS01','canSubmitDS02','canReturnDS03','canReassignClosing'] from phase10k3_test.state where key='double_shift_context'),'059 Double Shift action context complete');
select phase10k3_test.assert((select value ?& array['bundle','expectedReturnAt','actualReturnAt','changeFeed','reassignmentState','openingSummary','closingSummary','pendingEventTransfers','ds04Summary'] from phase10k3_test.state where key='double_shift_context'),'060 Double Shift workspace complete');
select phase10k3_test.assert((select before.value=after.value from phase10k3_test.state before join phase10k3_test.state after on after.key='counts_after' where before.key='counts_before'),'061 reads and blocked writes create no operational data');
select phase10k3_test.assert((select not value ? 'operationLedger' and not value ? 'draftTemplates' from phase10k3_test.state where key='manager_home'),'062 manager-only data absent from employee home');
select phase10k3_test.assert((select jsonb_array_length(value->'reasonCodes')=1 from phase10k3_test.state where key='manager_home'),'063 access reason codes stable');
select phase10k3_test.assert((select value->>'uiReleaseStage'='staff_preview' from phase10k3_test.state where key='staff_home'),'064 staff sees staff_preview');
select phase10k3_test.assert((select value->>'mode'='shadow' from phase10k3_test.state where key='shared_home'),'065 shared operator sees shadow');
select phase10k3_test.assert((select not value::text~*'credential|secret|token' from phase10k3_test.state where key='task_context'),'066 task context contains no credential material');
select phase10k3_test.assert((select not value::text~*'routine_ui_operations|rawOperations' from phase10k3_test.state where key='run_context'),'067 run context contains no operation ledger');
select phase10k3_test.assert((select bool_and(prosecdef) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('get_routine_employee_home','get_routine_run_action_context','get_routine_task_action_context','get_routine_handover_action_context','get_routine_transfer_action_context','get_double_shift_action_context')),'068 reads are security definer');
select phase10k3_test.assert((select value->'offline'->>'serverCacheAuthoritative'='true' from phase10k3_test.state where key='manager_home'),'069 server cache remains authoritative');
select phase10k3_test.assert((select value->'offlinePolicy'->>'queuedDoesNotChangeRunStatus'='true' from phase10k3_test.state where key='run_context'),'070 queued finish does not change run status');
select phase10k3_test.assert((select not value::text~'(_auth_user_id|_operator_id|user_profile_id|creation_idempotency_key|operation_id|client_instance_id)' from phase10k3_test.state where key='run_context'),'071 run projection strips private actor and operation identifiers');
select phase10k3_test.assert((select not value::text~'(_auth_user_id|_operator_id|user_profile_id|creation_idempotency_key|operation_id|client_instance_id)' from phase10k3_test.state where key='task_context'),'072 task projection strips private actor and operation identifiers');
select phase10k3_test.assert((select not value::text~'(_auth_user_id|_operator_id|user_profile_id|creation_idempotency_key|operation_id|client_instance_id)' from phase10k3_test.state where key='handover_context'),'073 handover projection strips private actor and operation identifiers');
select phase10k3_test.assert((select not value::text~'(_auth_user_id|_operator_id|user_profile_id|creation_idempotency_key|operation_id|client_instance_id)' from phase10k3_test.state where key='transfer_context'),'074 transfer projection strips private actor and operation identifiers');
select phase10k3_test.assert((select not value::text~'(_auth_user_id|_operator_id|user_profile_id|creation_idempotency_key|operation_id|client_instance_id)' from phase10k3_test.state where key='double_shift_context'),'075 Double Shift projection strips private actor and operation identifiers');
select phase10k3_test.assert((select not value->'run' ? 'snapshotSources' from phase10k3_test.state where key='run_context'),'076 raw snapshot source payloads are omitted');
select phase10k3_test.assert((select case value->'initialAssessmentPolicy'->>'policy' when 'ready_on_arrival' then value->'initialAssessmentPolicy'->'allowedChoices'='["ready","correction_required"]'::jsonb when 'control_result' then value->'initialAssessmentPolicy'->'allowedChoices'='["ready","control_issue_found"]'::jsonb else value->'initialAssessmentPolicy'->'allowedChoices'='[]'::jsonb end from phase10k3_test.state where key='task_context'),'077 assessment choices exactly match lifecycle values');
select phase10k3_test.assert((select not value::text~*'server_required' from phase10k3_test.state where key='run_context'),'078 no invented run verification type');
select phase10k3_test.assert((select bool_and(not value::text~*'(credential_hash|session_secret|response_payload|result_payload)') from phase10k3_test.state where key in('run_context','task_context','handover_context','transfer_context','double_shift_context')),'079 no credential or operation result payload leaks');
select phase10k3_test.assert((select value->'reassignmentState' ?& array['closingParticipantId','history'] from phase10k3_test.state where key='double_shift_context'),'080 Double Shift reassignment uses server participant identity');
